// Preparar dados consolidados para persistir - v4.43
// Le output DIRETO do Validador Resposta IA (fonte autoritaria da resposta final).
// Nao usa $input.first().json.output porque pode estar contaminado pelo
// Backup: Insert Reuniao (nó Postgres substitui o item de entrada).

const vars = $('Variáveis').first().json;
const sessao = $('Resolver Sessão').first().json;

// Le output do Validador — fonte autoritaria (ja tem fallback aplicado se preciso)
let output = '';
try {
  output = String($('Validador Resposta IA').first().json.output ?? '').trim();
} catch (e) {
  // Fallback ultimo recurso: tenta $input
  try {
    const sdr = $input.first().json;
    output = String(sdr.output ?? sdr.text ?? '').trim();
  } catch (e2) {}
}

const now = new Date().toISOString();

return [{
  json: {
    telefone: vars.mobile,
    nome: sessao.nome,
    sessionid: sessao.sessionId,
    push_name: sessao.pushName,
    email: sessao.email,
    empresa: sessao.empresa,
    cidade: sessao.cidade,
    ultima_mensagem_cliente: sessao.listaMensagens,
    ultima_resposta_ia: output,
    ultimo_contato: now,
    updated_at: now,
    qtd_interacoes: sessao.qtd_interacoes,
    estado_funil: sessao.estado_funil,
    status_atendimento: sessao.status_atendimento,
    isNew: sessao.isNewCliente,
    sdrOutput: output
  }
}];

