// Parse e prepara para upsert
const resp = $input.first().json;
const choices = resp.choices || [];
if (choices.length === 0) return [{ json: { skip: true } }];

let parsed = {};
try {
  parsed = JSON.parse(choices[0].message.content);
} catch (e) {
  parsed = { resumo: choices[0].message.content, topicos: [], perfil_inferido: '', proximos_passos: '' };
}

const mobile = $('Variáveis').first().json.mobile;
return [{
  json: {
    telefone: mobile,
    resumo: parsed.resumo || '',
    topicos: Array.isArray(parsed.topicos) ? parsed.topicos.join(', ') : (parsed.topicos || ''),
    perfil_inferido: parsed.perfil_inferido || '',
    proximos_passos: parsed.proximos_passos || '',
    status_atendimento_apos: $('Resolver Sessão').first().json.status_atendimento || 'ativo',
    created_at: new Date().toISOString()
  }
}];

const body = $input.first().json.body || $input.first().json;
const startDay = body.startDay || new Date().toISOString().slice(0,10);
const endDay = body.endDay || startDay;
const audiencia = (body.audiencia || 'B2B').toUpperCase();
const force = body.force === true || body.force === 'true';

const cacheKey = `grdmad:calcache:${startDay}_${endDay}_${audiencia}`;
return [{ json: { startDay, endDay, audiencia, cacheKey, force } }];

// Cal: Compute Slots v4.54 — ranges diferenciados B2B vs B2C
// B2B: 08:00-17:45 (jornada inteira)
// B2C: 09:00-12:00 + 14:00-19:00 (pula horário comercial padrão de almoço)

const input = $('Cal: Parse Input').first().json;
const all = [];
try {
  const principal = ($('Cal: GET Principal').first().json.value || $('Cal: GET Principal').first().json.items || []);
  const b2b = ($('Cal: GET B2B').first().json.value || $('Cal: GET B2B').first().json.items || []);
  const b2c = ($('Cal: GET B2C').first().json.value || $('Cal: GET B2C').first().json.items || []);
  all.push(...principal, ...b2b, ...b2c);
} catch (e) {}

const busy = [];
for (const evt of all) {
  if (!evt) continue;
  const s = evt.start?.dateTime || evt.start?.date;
  const e = evt.end?.dateTime || evt.end?.date;
  if (!s || !e) continue;
  busy.push({ startISO: s, endISO: e, summary: evt.summary || '(sem titulo)' });
}

// === Configuracao de horario por audiencia ===
const audiencia = (input.audiencia || 'B2B').toUpperCase();
// Cada faixa eh [horaInicio, minutoInicio, horaFim, minutoFim]
const HORARIO_POR_AUDIENCIA = {
  B2B: [[8, 0, 17, 45]],                  // jornada toda
  B2C: [[9, 0, 12, 0], [14, 0, 19, 0]]    // 9-12 e 14-19 (sem almoco)
};
const faixas = HORARIO_POR_AUDIENCIA[audiencia] || HORARIO_POR_AUDIENCIA.B2B;
const SLOT_MIN = 30;
const TZ_OFFSET = '-03:00';

function pad(n) { return String(n).padStart(2, '0'); }
function toISO(d) {
  return d.getFullYear() + '-' + pad(d.getMonth()+1) + '-' + pad(d.getDate()) +
         'T' + pad(d.getHours()) + ':' + pad(d.getMinutes()) + ':00' + TZ_OFFSET;
}

const startDay = input.startDay;
const endDay = input.endDay || startDay;
const slots_livres = [];
const slots_ocupados = [];

// feriados nacionais + SP em 2026 (parcial; pode expandir)
const FERIADOS = new Set([
  '2026-01-01','2026-02-16','2026-02-17','2026-03-29','2026-04-21',
  '2026-05-01','2026-06-04','2026-07-09','2026-09-07','2026-10-12',
  '2026-11-02','2026-11-15','2026-11-20','2026-12-25'
]);

// Iterar dias no range
const dtStart = new Date(startDay + 'T00:00:00' + TZ_OFFSET);
const dtEnd = new Date(endDay + 'T23:59:59' + TZ_OFFSET);

for (let d = new Date(dtStart); d <= dtEnd; d.setDate(d.getDate() + 1)) {
  const dateStr = d.getFullYear() + '-' + pad(d.getMonth()+1) + '-' + pad(d.getDate());
  const dow = d.getDay(); // 0=domingo, 6=sabado
  if (dow === 0 || dow === 6) continue;
  if (FERIADOS.has(dateStr)) continue;

  // Pra cada FAIXA da audiencia, gerar slots
  for (const [h0, m0, hF, mF] of faixas) {
    for (let h = h0, m = m0; (h < hF) || (h === hF && m < mF); ) {
      const slotStart = new Date(d.getFullYear(), d.getMonth(), d.getDate(), h, m, 0);
      const slotEnd = new Date(slotStart.getTime() + SLOT_MIN * 60 * 1000);

      // Conflito? Compara ISO strings (ambos no mesmo TZ)
      const ssISO = toISO(slotStart);
      const seISO = toISO(slotEnd);
      const conflito = busy.find(b => !(b.endISO <= ssISO || b.startISO >= seISO));

      const slotInfo = {
        date: dateStr,
        time: pad(h) + ':' + pad(m),
        startISO: ssISO,
        endISO: seISO,
        diaSemana: ['domingo','segunda','terca','quarta','quinta','sexta','sabado'][dow]
      };

      if (conflito) {
        slots_ocupados.push({ ...slotInfo, conflito_com: conflito.summary });
      } else {
        slots_livres.push(slotInfo);
      }

      // proximo slot
      m += SLOT_MIN;
      if (m >= 60) { h += Math.floor(m/60); m = m % 60; }
    }
  }
}

return [{
  json: {
    audiencia,
    startDay,
    endDay,
    range_horario: faixas.map(f => pad(f[0])+':'+pad(f[1])+'-'+pad(f[2])+':'+pad(f[3])).join(', '),
    slots_livres,
    slots_ocupados,
    total_livres: slots_livres.length,
    total_ocupados: slots_ocupados.length
  }
}];

