const metricasGerais = $('PG: Métricas Gerais').first()?.json || {};
const porDia = $('PG: Métricas Por Dia').all().map(i => i.json);
const horarios = $('PG: Horários Populares').all().map(i => i.json);
const funil = $('PG: Funil').all().map(i => i.json);
const tempoAg = $('PG: Tempo Até Agendamento').all().map(i => i.json);

return [{
  json: {
    timestamp: new Date().toISOString(),
    periodo: 'últimos 30 dias',
    overview: {
      leads_total: parseInt(metricasGerais.leads_30d) || 0,
      reunioes_total: parseInt(metricasGerais.reunioes_30d) || 0,
      reunioes_b2b: parseInt(metricasGerais.reunioes_b2b_30d) || 0,
